import { leafBlocks, type DocDoc } from '@morph/tool-office';
import { useEffect, useMemo, useState } from 'react';
import { ActivityIndicator, StyleSheet, View } from 'react-native';
import { WebView } from 'react-native-webview';

import type { Palette } from '../renderer/theme';
import { jpegDataUrl, wordPageHtml } from './word-page';

// Word on the preview page (D-470): Word converted and saved by Tinkrum renders according to the
// editor layout (view-only), no longer showing "this file cannot be displayed" (Android system
// cannot display Word). Pages are fixed HTML generated by ourselves, offline.

export function WordPreview({
  doc,
  width,
  palette,
  readImage,
}: {
  doc: DocDoc;
  width: number;
  palette: Palette;
  readImage: (uri: string) => Promise<Uint8Array>;
}) {
  const [images, setImages] = useState<Record<string, string> | null>(null);
  useEffect(() => {
    let alive = true;
    const srcs = [
      ...new Set(
        doc.pages.flatMap((p) =>
          leafBlocks(p).flatMap((b) => (b.kind === 'image' && b.src ? [b.src] : [])),
        ),
      ),
    ];
    void Promise.all(
      srcs.map((src) =>
        readImage(src).then(
          (bytes) => [src, jpegDataUrl(bytes)] as const,
          () => null,
        ),
      ),
    ).then((pairs) => {
      if (alive) setImages(Object.fromEntries(pairs.filter((p) => p !== null)));
    });
    return () => {
      alive = false;
    };
    // Re-read only when the document changes; the file reading function is new on every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [doc]);
  const html = useMemo(
    () => (images ? wordPageHtml(doc, width, images, false, null, true) : null),
    [doc, width, images],
  );
  if (!html) return <ActivityIndicator style={styles.flex} color={palette.primary} />;
  return (
    <View style={styles.flex}>
      <WebView
        testID="word-preview-page"
        style={styles.flex}
        source={{ html, baseUrl: 'about:blank' }}
        originWhitelist={['*']}
        onShouldStartLoadWithRequest={(r) => r.url === 'about:blank' || r.url.startsWith('data:')}
        javaScriptEnabled={false}
        allowFileAccess={false}
        setSupportMultipleWindows={false}
        textZoom={100}
      />
    </View>
  );
}

const styles = StyleSheet.create({ flex: { flex: 1 } });
